'use strict';
const D=window.NL_DATA,E=window.NL_ENGINE;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const STORAGE='network-lab-educational-v1';
const defaults={module:'lan',view:'lab',scenarios:{},flags:{},done:[],gpon:{km:24,atten:.35,ratio:64,connectors:6,splices:5,tx:2,sens:-28},fiveg:{radius:24,sites:[{x:50,y:30}]},student:{name:'',group:''},quizResult:null};
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE)||'{}')}catch(_e){}
const state={...clone(defaults),...saved};if(!D.modules.some(m=>m.id===state.module))state.module='lan';if(!['lab','theory','osi','gpon','5g','quiz'].includes(state.view))state.view='lab';
let selected=null,selectedLink=null,connectMode=false,connectOrigin=null,media='ethernet',lastDiag={},lastPing={},quiz=null,osiLayer=7,showReport=false,dragging=null,suppressClick=false,siteDrag=null,subnetInput={ip:'192.168.10.42',prefix:24};
function scenario(id=state.module){if(!state.scenarios[id]||!Array.isArray(state.scenarios[id].nodes)){let p=clone(D.scenarios[id]);p.links=p.links.map((l,i)=>({id:`edge${i+1}`,...l,meters:l.meters??20}));p.counter=20;state.scenarios[id]=p;}return state.scenarios[id];}
function flags(id=state.module){return state.flags[id]??(state.flags[id]={pingSuccess:false,ranDiag:false,dhcpUsed:false,dnsUsed:false,osiExplored:[],osiTrace:false});}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({module:state.module,view:state.view,scenarios:state.scenarios,flags:state.flags,done:state.done,gpon:state.gpon,fiveg:state.fiveg,student:state.student,quizResult:state.quizResult}))}catch(e){console.warn('Не вдалося зберегти прогрес',e)}}
function mod(){return D.modules.find(x=>x.id===state.module)}
function toast(msg,kind='ok'){const el=document.createElement('div');el.className=`toast ${kind==='error'?'error':kind==='warn'?'warn':''}`;el.textContent=msg;$('#toasts').append(el);setTimeout(()=>el.remove(),4700)}
function icon(type){const paths={pc:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M9 21h6M12 17v4"/>',laptop:'<path d="M5 4h14v12H5zM2 20h20l-3-4H5z"/>',switch:'<rect x="2" y="7" width="20" height="10" rx="2"/><path d="M6 11h2m3 0h2m3 0h2M6 14h12"/>',router:'<rect x="3" y="9" width="18" height="9" rx="2"/><path d="M7 9V5m10 4V5M7 4l-2-2m12 2 2-2M7 14h3m4 0h3"/>',server:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h7M8 11h7M8 16h7"/><circle cx="16" cy="19" r=".8"/>',ap:'<path d="M12 19v-6m-6 8h12M4 10a11 11 0 0 1 16 0m-12 3a5 5 0 0 1 8 0"/><circle cx="12" cy="12" r="1"/>',olt:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M6 10h12M6 14h12M9 2v3m6-3v3M9 19v3m6-3v3"/>',splitter:'<path d="M3 12h8M11 12l8-7M11 12l8 0M11 12l8 7"/><circle cx="19" cy="5" r="2"/><circle cx="19" cy="12" r="2"/><circle cx="19" cy="19" r="2"/>',ont:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M7 10h10M7 14h10"/><circle cx="18" cy="18" r="1"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" aria-hidden="true">${paths[type]||paths.pc}</svg>`;}
const nBy=(id,s=scenario())=>s.nodes.find(n=>n.id===id);
function devicesLabel(){return Object.entries(D.deviceTypes).map(([t,d])=>`<button class="palette-item" data-action="add-device" data-type="${t}" draggable="true" data-drag-type="${t}" title="Додати ${d.label}"><span class="palette-icon">${icon(t)}</span>${safe(d.short)}</button>`).join('');}
function showNav(){const nav=$('#moduleNav');nav.innerHTML=D.modules.map(m=>`<button class="side-mod ${state.module===m.id?'active':''}" data-action="module" data-id="${m.id}"><span class="mod-index">${m.n}</span><span class="mod-body"><strong>${safe(m.title)}</strong><small>${safe(m.short)}</small></span><span class="mod-tick">${state.done.includes(m.id)?'✓':'›'}</span></button>`).join('');$('#sideProgressText').textContent=`${state.done.length} / 8`;$('#sideProgressFill').style.width=`${12.5*state.done.length}%`;}
function showHeader(){const m=mod();$('#currentChapter').textContent=`МОДУЛЬ ${m.n} · ${m.short.toUpperCase()}`;$('#moduleTitle').textContent=m.title;$('#moduleDesc').textContent=m.desc;const status=$('#chapterStatus');status.className='chapter-status'+(state.done.includes(state.module)?' ok':'');status.textContent=state.done.includes(state.module)?'✓ Місія виконана':'◌ Місія не завершена';$$('#viewTabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));}
function render(){showNav();showHeader();showReport=false;const root=$('#viewRoot');root.innerHTML=state.view==='lab'?renderLab():state.view==='theory'?renderTheory():state.view==='osi'?renderOSI():state.view==='gpon'?renderGPON():state.view==='5g'?render5G():renderQuiz();persist();}
function missionTasks(){const id=state.module,s=scenario(),f=flags(),r=E.check(s,s.from,s.to);const linked=(a,b,medium)=>s.links.some(l=>((l.a===a&&l.b===b)||(l.a===b&&l.b===a))&&l.up&&E.supported(l,s)&&(medium?l.media===medium:true));
 switch(id){case 'lan':return [s.nodes.every(n=>!n.off),linked('pc1','sw1','ethernet'),linked('pc2','sw1','ethernet'),E.sameNetwork(nBy('pc1'),nBy('pc2')),f.pingSuccess&&r.ok];
 case 'route':return [E.path(s,'pc1','srv')!==null,nBy('pc1')?.gateway==='192.168.10.1',nBy('srv')?.gateway==='192.168.20.1',!nBy('r1')?.off,f.pingSuccess&&r.ok];
 case 'ip':return [nBy('pc1')&&E.isIP(nBy('pc1').ip)&&E.network(nBy('pc1').ip,nBy('pc1').prefix)==='192.168.10.0',nBy('pc2')&&E.isIP(nBy('pc2').ip)&&E.network(nBy('pc2').ip,nBy('pc2').prefix)==='192.168.10.0',E.sameNetwork(nBy('pc1'),nBy('pc2')),nBy('pc1')?.ip!==nBy('pc2')?.ip,f.pingSuccess&&r.ok];
 case 'osi':return [r.ok,E.sameNetwork(nBy('pc1'),nBy('pc2')),f.osiExplored?.length>=1,f.osiExplored?.length>=7,f.pingSuccess&&r.ok];
 case 'services':return [!!nBy('r1')?.dhcpServer,!!f.dhcpUsed&&nBy('pc1')?.ip==='192.168.10.100',!!nBy('dns1')?.dnsServer,!!f.dnsUsed,!!nBy('r1')?.nat];
 case 'fault':return [!!f.ranDiag,linked('pc2','sw1','ethernet'),nBy('pc2')?.ip==='192.168.30.20',E.sameNetwork(nBy('pc1'),nBy('pc2')),f.pingSuccess&&r.ok];
 case 'gpon':return [linked('olt1','split1','fiber')&&linked('split1','ont1','fiber'),linked('ont1','pc1','ethernet'),E.optical(state.gpon).margin>=3,E.optical(state.gpon).margin>=3,!!E.path(s,'olt1','pc1')];
 case '5g':return [!!f.viewed5g,state.fiveg.sites.length>=1,state.fiveg.sites.length<=3,E.coverage(state.fiveg).percent>=85,E.coverage(state.fiveg).percent>=85];
 default:return [];
 }
}
function missionIsComplete(){const tasks=missionTasks();return tasks.length>0&&tasks.every(Boolean)&&E.diagnose(scenario(),state.module,state.gpon).filter(x=>x.level==='error').length===0;}
function missionSummaryHTML(){const m=mod(),tasks=missionTasks();return `<div class="panel mission-guide"><h4>Критерії виконання</h4><ul class="mission-task-list">${m.tasks.map((t,i)=>`<li class="${tasks[i]?'complete':''}"><span class="task-check">${tasks[i]?'✓':''}</span>${safe(t)}</li>`).join('')}</ul><button class="btn btn-plain" data-action="check-mission" style="margin-top:13px;width:100%">✓ Перевірити виконання</button></div>`;}
function renderLab(){let s=scenario(),m=mod(),items=lastDiag[state.module]||E.diagnose(s,state.module,state.gpon);return `<div class="lab-overview"><div class="mission-card"><div><div class="mission-label">ПРАКТИЧНА МІСІЯ ${m.n} / 08</div><h3>${safe(m.mission)}</h3><p>${safe(m.objective)}</p><div class="mission-target"><span class="target-pill">Автоматична діагностика</span><span class="target-pill">Підказки до помилок</span><span class="target-pill">Звіт PDF</span></div></div><div class="mission-actions"><button class="btn btn-accent" data-action="check-mission">Перевірити ✓</button><button class="btn btn-glass" data-action="reset">↺ Скинути</button></div></div>${missionSummaryHTML()}</div><div class="work-grid"><div><div class="panel canvas-panel"><div class="panel-head"><div><h3>Робочий стенд · Топологія мережі</h3><p>Перетягни вузол для переміщення. Натисни вузол для налаштування.</p></div><span class="small-tag">LIVE SIM</span></div><div class="tool-strip"><button class="tool-mini ${connectMode?'selected':''}" data-action="connect-mode">${connectMode?'✓ Завершити з’єднання':'＋ З’єднати'}</button><label style="font-size:10px;color:#70878f;font-weight:800">Кабель</label><select id="mediaSelect"><option value="ethernet" ${media==='ethernet'?'selected':''}>Ethernet (мідь)</option><option value="fiber" ${media==='fiber'?'selected':''}>Оптоволокно</option><option value="wireless" ${media==='wireless'?'selected':''}>Бездротовий</option></select><div class="tool-spacer"></div><button class="tool-mini" data-action="diagnose">◉ Діагностика</button><button class="tool-mini warn" data-action="hint">? Підказка</button></div><div class="palette"><span class="palette-label">ДОДАТИ ПРИСТРІЙ</span>${devicesLabel()}</div><div class="canvas-scroll"><div class="network-canvas ${connectMode?'link-mode':''}" id="networkCanvas"><svg class="connections-svg" id="connectionsSvg" viewBox="0 0 1000 540" preserveAspectRatio="none">${renderConnections()}</svg>${s.nodes.map(renderDevice).join('')}<div class="canvas-watermark">NETWORK LAB / TOPOLOGY VIEW</div></div></div><div class="canvas-legend"><span><i class="legend-line"></i> Ethernet</span><span><i class="legend-line fiber"></i> Оптика</span><span><i class="legend-line bad"></i> Помилка / Down</span></div><div class="ping-bar"><label>Від</label><select id="pingFrom">${s.nodes.map(n=>`<option value="${n.id}" ${n.id===s.from?'selected':''}>${safe(n.label)}</option>`).join('')}</select><label>до</label><select id="pingTo">${s.nodes.map(n=>`<option value="${n.id}" ${n.id===s.to?'selected':''}>${safe(n.label)}</option>`).join('')}</select><button class="btn btn-blue" data-action="ping">▸ ${state.module==='gpon'||state.module==='5g'?'Перевірити шлях':'Запустити Ping'}</button>${state.module==='services'?'<button class="btn btn-plain" data-action="dns-query">DNS-запит</button>':''}</div><div class="ping-output" id="pingOutput">${lastPing[state.module]?safe(lastPing[state.module]):'<span class="dim">NETWORK LAB / CLI · Готово до тестування. Налаштуй стенд та натисни «Запустити Ping».</span>'}</div></div><section class="panel diagnostic-panel"><div class="diagnostic-head"><div><b>Центр діагностики</b><p style="font-size:10px;color:#7b919a;margin:3px 0 0">Кожен збій супроводжується поясненням і способом виправлення</p></div><span class="diag-count">${items.filter(x=>x.level==='error').length} критичних · ${items.filter(x=>x.level==='warn').length} попереджень</span></div><div class="diagnostic-grid" id="diagnosticList">${items.map(diagnosticCard).join('')}</div></section></div><aside class="panel inspector-panel"><div class="panel-head"><div><h3>Інспектор обладнання</h3><p>Параметри обраного об’єкта</p></div></div><div class="panel-body" id="inspectorRoot">${renderInspector()}</div></aside></div><div class="note-banner"><b>Навчальне зауваження.</b> Топологія, Ping, DHCP, DNS та маршрутизація тут спрощені для пояснення принципів. Це не мережевий емулятор і не перевірка фактичних портів обладнання. Для поглибленої роботи використовуй Cisco Packet Tracer, GNS3 чи реальне лабораторне обладнання.</div>`;}
function renderConnections(){const s=scenario();return s.links.map(l=>{const a=nBy(l.a,s),b=nBy(l.b,s);if(!a||!b)return '';const invalid=!E.supported(l,s)||!l.up;const c=invalid?'#da6869':l.media==='fiber'?'#738aca':l.media==='wireless'?'#a678b8':'#22ac9d';const dash=invalid?'5 6':l.media==='fiber'?'11 6':l.media==='wireless'?'3 6':'';const ax=a.x*10,ay=a.y*5.4,bx=b.x*10,by=b.y*5.4;return `<g><path d="M${ax} ${ay} L${bx} ${by}" stroke="transparent" stroke-width="18" fill="none" data-action="select-link" data-id="${safe(l.id)}"/><path d="M${ax} ${ay} L${bx} ${by}" stroke="${c}" stroke-width="3.5" ${dash?`stroke-dasharray="${dash}"`:''} fill="none" style="pointer-events:none"/><circle cx="${(ax+bx)/2}" cy="${(ay+by)/2}" r="6" fill="${c}" stroke="#fff" stroke-width="2" pointer-events="none"/></g>`;}).join('');}
function renderDevice(n){return `<button class="net-node ${selected===n.id?'active':''} ${connectOrigin===n.id?'connect-origin':''} ${n.off?'device-off':''}" style="left:${n.x}%;top:${n.y}%" data-id="${safe(n.id)}" data-action="select-device" aria-label="${safe(n.label)}, ${safe(D.deviceTypes[n.type].label)}"><span class="node-icon">${icon(n.type)}</span><span class="node-title">${safe(n.label)}</span><span class="node-ip">${safe(n.ip&&n.ip!=='0.0.0.0'?n.ip:n.type.toUpperCase())}</span><span class="node-port"></span></button>`;}
function diagnosticCard(i){return `<div class="diag-item ${safe(i.level)}"><div class="diag-head"><span>${i.level==='error'?'✕':i.level==='warn'?'!':i.level==='ok'?'✓':'i'} ${safe(i.title)}</span><span class="small-tag ${i.level==='error'?'danger':i.level==='info'?'info':''}">${i.level==='error'?'ПОМИЛКА':i.level==='warn'?'УВАГА':i.level==='ok'?'OK':'INFO'}</span></div><p>${safe(i.why)}</p><div class="diag-fix"><b>Як виправити: </b>${safe(i.fix)}</div>${i.focus?`<button class="diag-action" data-action="focus-node" data-id="${safe(i.focus)}">Відкрити налаштування →</button>`:''}${i.link?`<button class="diag-action" data-action="focus-link" data-id="${safe(i.link)}">Відкрити кабель →</button>`:''}</div>`;}
function field(label,key,val,opts={}){let content;if(opts.options){content=`<select data-field="${key}">${opts.options.map(o=>`<option value="${safe(o.value)}" ${String(val)===String(o.value)?'selected':''}>${safe(o.text)}</option>`).join('')}</select>`}else{content=`<input type="${opts.type||'text'}" data-field="${key}" value="${safe(val??'')}" ${opts.min!=null?`min="${opts.min}"`:''} ${opts.max!=null?`max="${opts.max}"`:''} ${opts.placeholder?`placeholder="${safe(opts.placeholder)}"`:''}>`;}return `<label class="field ${opts.full?'full':''}"><span>${safe(label)}</span>${content}</label>`;}
function renderInspector(){const s=scenario();if(selectedLink){const l=s.links.find(x=>x.id===selectedLink);if(!l){selectedLink=null;return renderInspector()}return `<div class="inspector-title"><div class="node-icon">↔</div><div><h4>Кабель: ${safe(nBy(l.a)?.label)} ↔ ${safe(nBy(l.b)?.label)}</h4><small>Налаштування фізичного каналу</small></div></div><div class="form-grid">${field('Носій','media',l.media,{full:true,options:[{value:'ethernet',text:'Ethernet (мідний)'},{value:'fiber',text:'Оптичне волокно'},{value:'wireless',text:'Бездротове з’єднання'}]})}${field('Довжина, м','meters',l.meters??20,{type:'number',min:1,max:30000})}</div><label class="switch-field">Канал увімкнений <input type="checkbox" data-field="up" ${l.up?'checked':''}></label><p class="muted-help">У реальних мережах допустимість кабелю визначається фізичними інтерфейсами, трансиверами та стандартом. Непідтримуваний тип з’єднання позначається червоним.</p><div class="form-actions"><button class="btn btn-danger" data-action="delete-link">Видалити кабель</button><button class="btn btn-plain" data-action="diagnose">Перевірити</button></div>`;}
 if(!selected){return `<div class="inspector-empty"><div>⬡</div><h4>Оберіть елемент схеми</h4><p>Натисни на пристрій або кабель. Тут можна змінити мережеві параметри, увімкнути служби та виправити помилки.</p></div>`;}
 let n=nBy(selected);if(!n){selected=null;return renderInspector()}const t=D.deviceTypes[n.type];let common=`<div class="inspector-title"><span class="node-icon">${icon(n.type)}</span><div><h4>${safe(n.label)}</h4><small>${safe(t.label)} · ${t.ports} порт(ів)</small></div></div><div class="form-grid">${field('Назва пристрою','label',n.label,{full:true})}</div><label class="switch-field">Живлення <input type="checkbox" data-field="on" ${!n.off?'checked':''}></label>`;
 if(t.ip)common+=`<div class="mini-section">МЕРЕЖЕВІ НАЛАШТУВАННЯ</div><div class="form-grid">${field('IPv4-адреса','ip',n.ip||'0.0.0.0',{full:true})}${field('Префікс CIDR','prefix',n.prefix??24,{type:'number',min:0,max:32})}${field('Шлюз','gateway',n.gateway||'',{full:true,placeholder:'192.168.10.1'})}${field('DNS-сервер','dns',n.dns||'',{full:true,placeholder:'192.168.20.53'})}</div><label class="switch-field">Отримувати IP через DHCP <input type="checkbox" data-field="dhcp" ${n.dhcp?'checked':''}></label>${n.dhcp?`<button class="btn btn-plain" style="margin-top:10px;width:100%" data-action="dhcp">↻ DHCP-запит</button>`:''}`;
 if(n.type==='router')common+=`<div class="mini-section">МЕРЕЖЕВІ СЛУЖБИ</div><div class="alert-compact">Інтерфейси навчального R-1:<br>${(n.networks||[]).map(x=>`<b>${safe(x)}</b>`).join('<br>')||'Немає налаштованих інтерфейсів'}</div><label class="switch-field">DHCP-сервер <input type="checkbox" data-field="dhcpServer" ${n.dhcpServer?'checked':''}></label><label class="switch-field">NAT / PAT <input type="checkbox" data-field="nat" ${n.nat?'checked':''}></label>`;
 if(n.type==='server')common+=`<div class="mini-section">СЕРВЕРНІ СЛУЖБИ</div><label class="switch-field">DNS-сервер (lab.example) <input type="checkbox" data-field="dnsServer" ${n.dnsServer?'checked':''}></label>`;
 if(n.type==='olt'||n.type==='splitter'||n.type==='ont')common+=`<p class="muted-help">GPON-пристрої з’єднуються оптоволокном, ONT має Ethernet-порт для підключення клієнтського обладнання.</p><button class="btn btn-plain" data-action="go-gpon" style="width:100%;margin-top:12px">Відкрити розрахунок GPON →</button>`;
 common+=`<div class="mini-section">ПІДКЛЮЧЕННЯ</div>${s.links.filter(l=>l.a===n.id||l.b===n.id).map(l=>`<div class="link-row">${safe(nBy(l.a===n.id?l.b:l.a)?.label)} · ${safe(l.media)} · ${l.up?'UP':'DOWN'}</div>`).join('')||'<p class="muted-help">Немає кабельних з’єднань.</p>'}<div class="form-actions"><button class="btn btn-danger" data-action="delete-device">Видалити</button><button class="btn btn-plain" data-action="diagnose">Перевірити</button></div>`;return common;}
function renderTheory(){const m=mod();const sub=E.calcSubnet(subnetInput.ip,+subnetInput.prefix);return `<div class="theory-intro mission-card"><div><div class="mission-label">ТЕОРЕТИЧНИЙ КОНСПЕКТ / МОДУЛЬ ${m.n}</div><h3>${safe(m.title)}</h3><p>${safe(m.desc)}</p></div><button class="btn btn-accent" data-action="go-lab">До практики ↗</button></div><div class="theory-layout"><div><div class="facts-list">${m.theory.map((f,i)=>`<article class="fact-card"><div class="kicker">${String(i+1).padStart(2,'0')} / ${m.theory.length}</div><h3>${safe(f[0])}</h3><p>${safe(f[1])}</p><div class="fact-example"><b>Приклад / кейс:</b> ${safe(f[2])}</div></article>`).join('')}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><h3>IP-калькулятор</h3><p>Введи адресу й префікс, щоб побачити діапазон підмережі</p></div></div><div class="panel-body"><div class="form-grid">${field('IPv4-адреса','subnet-ip',subnetInput.ip)}${field('CIDR','subnet-prefix',subnetInput.prefix,{type:'number',min:0,max:32})}</div><button class="btn btn-blue" style="margin:12px 0" data-action="subnet-calc">Розрахувати →</button><div id="subnetResult">${renderSubnetResult(sub)}</div></div></div></div><aside><div class="panel glossary-panel"><div class="panel-head"><div><h3>Словник термінів</h3><p>Ключові поняття модуля</p></div></div><div class="panel-body">${m.terms.map(t=>`<div class="glossary-entry"><strong>${safe(t[0])}</strong><p>${safe(t[1])}</p></div>`).join('')}</div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><h3>Джерела й стандарти</h3><p>Матеріали для поглибленого вивчення</p></div></div><div class="panel-body"><div class="reference-links">${D.sources.map(s=>`<a href="${safe(s[1])}" target="_blank" rel="noopener noreferrer">↗ ${safe(s[0])}</a>`).join('')}</div></div></div></aside></div><div class="note-banner"><b>Порада:</b> після опрацювання теорії відкрий «Мережевий стенд», виконай місію та пройди підсумкове тестування.</div>`;}
function renderSubnetResult(r){return r?`<table class="breakdown-table"><tbody>${[['Адреса мережі',r.network],['Маска',r.mask],['Broadcast',r.broadcast],['Перша адреса',r.first],['Остання адреса',r.last],['Усього адрес',r.total.toLocaleString('uk-UA')],['Типово для хостів',r.usable.toLocaleString('uk-UA')]].map(x=>`<tr><td>${x[0]}</td><td><b>${x[1]}</b></td></tr>`).join('')}</tbody></table><p class="source-note">Для /31 та /32 кількість адрес подано з урахуванням винятків для point-to-point і host routes.</p>`:'<div class="error-guidance">Помилка: IPv4 має містити 4 числа від 0 до 255, префікс — 0–32.</div>';}
const OSI=[
 {n:7,name:'Прикладний',pdu:'Дані застосунку',protocol:'HTTP, DNS, SMTP',desc:'Служби, з якими працюють користувацькі програми. Звернення до вебсервера, пошук DNS-записів, надсилання пошти. Це не те саме, що кожна програма реалізує всі протоколи.',example:'Браузер формує HTTP-запит до сервера.'},
 {n:6,name:'Представлення',pdu:'Дані',protocol:'Формати, кодування, концептуально TLS',desc:'Представлення даних у зрозумілому вигляді: кодування, серіалізація, перетворення, шифрування. У реальному TCP/IP-стеку функції цього рівня не завжди виділені окремим шаром.',example:'Текст кодується UTF-8; дані можуть шифруватися на рівні застосунків.'},
 {n:5,name:'Сеансовий',pdu:'Дані',protocol:'Контроль сеансів',desc:'Організація і контроль взаємодії між процесами, керування станом сеансу. У TCP/IP відповідні функції часто реалізуються протоколами або застосунками без окремого універсального шару.',example:'Встановлення і підтримка логіки сеансу в застосунку.'},
 {n:4,name:'Транспортний',pdu:'Сегмент / датаграма',protocol:'TCP, UDP, QUIC поверх UDP',desc:'Розділення даних за портами, забезпечення доставки між процесами. TCP має підтвердження, контроль і повторні передачі; UDP передає датаграми без гарантій на цьому рівні.',example:'HTTPS через TCP використовує типово 443; HTTP/3 — QUIC поверх UDP/443.'},
 {n:3,name:'Мережевий',pdu:'IP-пакет',protocol:'IPv4, IPv6, ICMP',desc:'Логічна адресація вузлів та маршрутизація між мережами. Маршрутизатор використовує таблицю маршрутів. Для Ping ICMP Echo передається без TCP/UDP.',example:'IP 192.168.10.10 надсилає пакет до 192.168.20.10 через маршрутизатор.'},
 {n:2,name:'Канальний',pdu:'Кадр',protocol:'Ethernet, Wi-Fi, ARP для IPv4',desc:'Передача кадрів у межах канального сегмента, MAC-адресація й контроль доступу до середовища. Комутатор L2 звичайно працює з Ethernet-кадрами.',example:'Комутатор шукає MAC-адресу призначення у своїй таблиці.'},
 {n:1,name:'Фізичний',pdu:'Біти / сигнал',protocol:'1000BASE-T, оптичні інтерфейси',desc:'Електричне, оптичне або радіочастотне передавання бітів по фізичному середовищу. Параметри включають рівень сигналу, кодування лінії, оптичний бюджет, тип трансивера.',example:'Імпульси поширюються по витій парі або оптичному волокну.'}
];
function renderOSI(){const l=OSI.find(x=>x.n===osiLayer),f=flags();return `<div class="mission-card" style="margin-bottom:16px"><div><div class="mission-label">АНІМОВАНА КОНЦЕПТУАЛЬНА МОДЕЛЬ</div><h3>Як дані проходять мережею</h3><p>Натискай на кожен рівень. Зауваж: ICMP Echo (Ping) не використовує транспортний TCP/UDP. Сім рівнів — концептуальна модель.</p></div><button class="btn btn-accent" data-action="osi-play">▸ Показати шлях</button></div><div class="osi-grid"><div class="panel"><div class="panel-head"><h3>7 рівнів OSI</h3><span class="small-tag">${f.osiExplored?.length||0} / 7</span></div><div class="panel-body">${OSI.map(o=>`<button class="osi-layer ${o.n===osiLayer?'active':''}" data-action="osi-layer" data-n="${o.n}"><span class="layer-n">L${o.n}</span><span style="flex:1">${o.name}</span><small>${o.pdu}</small>${f.osiExplored?.includes(o.n)?'✓':''}</button>`).join('')}</div></div><div class="panel osi-visual"><div class="panel-head"><div><h3>Рівень L${l.n} — ${l.name}</h3><p>${l.pdu} · ${l.protocol}</p></div></div><div class="panel-body"><div class="kicker">ЩО ВІДБУВАЄТЬСЯ</div><p>${l.desc}</p><div class="osi-bits">${l.n>=5?'DATA':l.n===4?'[DATA]':l.n===3?'[IP] + DATA':l.n===2?'[MAC]+[IP]':'01010110'}</div><div class="fact-example"><b>Приклад:</b> ${l.example}</div><hr class="sep"><div class="kicker">ШЛЯХ ПАКЕТА</div><div class="packet-journey" id="osiSteps">${['Застосунок','Інкапсуляція','Кадр Ethernet','Комутатор','Декапсуляція','Відповідь'].map((x,i)=>`<span class="packet-step" data-packet-step="${i}">${i+1}. ${x}</span>`).join('')}</div><p class="muted-help">Анімація навчальна: час обробки пакетів і кадрів не моделюється. Для практичного Ping відкрий мережевий стенд.</p><button class="btn btn-plain" data-action="go-lab" style="margin-top:11px">Перевірити Ping на стенді ↗</button></div></div></div>`;}
function renderGPON(){const o=E.optical(state.gpon),s=state.gpon;const control=(label,key,min,max,step,unit)=>`<label class="field full"><span>${label}: <strong>${s[key]} ${unit}</strong></span><input style="width:100%;accent-color:#21aea5" type="range" data-gpon="${key}" min="${min}" max="${max}" step="${step}" value="${s[key]}"></label>`;return `<div class="mission-card" style="margin-bottom:16px"><div><div class="mission-label">ОПТИЧНА ЛАБОРАТОРІЯ / РОЗРАХУНОК</div><h3>GPON Optical Budget</h3><p>Змінюй параметри лінії та спостерігай, як вони впливають на потужність приймання. Модельні втрати орієнтовні.</p></div><button class="btn btn-accent" data-action="go-lab">На стенд ↗</button></div><div class="device-calc-grid"><div class="panel"><div class="panel-head"><div><h3>Параметри оптичного тракту</h3><p>OLT → оптичне волокно → splitter → ONT</p></div></div><div class="panel-body"><div class="form-grid">${control('Довжина кабелю','km',1,30,.5,'км')}${control('Загасання волокна','atten',.2,.5,.05,'дБ/км')}${control('Потужність передавача','tx',-2,7,.5,'дБм')}${control('Чутливість приймача (навчальна)','sens',-32,-20,1,'дБм')}${control('Кількість конекторів','connectors',2,12,1,'шт.')}${control('Кількість зварок','splices',0,16,1,'шт.')}${field('Коефіцієнт спліттера','gpon-ratio',s.ratio,{full:true,options:[2,4,8,16,32,64].map(n=>({value:n,text:`1:${n}`}))})}</div><div class="formula" style="margin-top:20px">P_rx = P_tx − (α×L + L_сплітер + N_кон×0.3 + N_зв×0.1)<br>Запас = P_rx − P_min</div><div class="source-note">Поріг 3 дБ — навчальний резерв, не універсальна вимога GPON. Реальні класи оптики й приймальні пороги див. у документації виробника та ITU-T G.984.</div></div></div><div><div class="calc-result"><div class="calc-label">ЗАПАС ОПТИЧНОЇ ПОТУЖНОСТІ</div><div class="calc-number ${o.ok?'':'bad'}" id="opticalNumber">${o.margin.toFixed(2)} <small style="font-size:18px">дБ</small></div><p id="opticalStatus">${o.ok?'✓ Навчальний запас достатній (≥ 3 дБ).':'✕ Запас менший за 3 дБ. Зменш втрати або зміни параметри тракту.'}</p><div class="calc-kpis"><div><b id="opticalLoss">${o.total.toFixed(2)} дБ</b><small>Загальні втрати</small></div><div><b id="opticalRx">${o.rx.toFixed(2)} дБм</b><small>Потужність ONT</small></div></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h3>Деталізація втрат</h3></div><div class="panel-body" id="opticalBreakdown">${renderOpticalBreakdown(o)}</div></div><div class="panel" style="margin-top:16px"><div class="panel-body"><div class="kicker">ПОШУК ПОМИЛОК</div><p style="font-size:11px;color:#5f7c86">За недостатнього бюджету спробуй: зменшити спліт 1:64 → 1:16, скоротити трасу, кількість зварок та конекторів. Повернися до стенда та перевір кабелі.</p><button class="btn btn-blue" data-action="check-mission">Перевірити місію →</button></div></div></div></div>`;}
function renderOpticalBreakdown(o){return `<table class="breakdown-table"><tr><th>Складник</th><th>Втрати</th></tr>${[['Волокно',o.fiber],['Сплітер',o.split],['Конектори',o.connectors],['Зварки',o.splices],['Разом',o.total]].map(x=>`<tr><td>${x[0]}</td><td><b>${x[1].toFixed(2)} дБ</b></td></tr>`).join('')}</table>`;}
function render5G(){const cov=E.coverage(state.fiveg),s=state.fiveg;return `<div class="mission-card" style="margin-bottom:16px"><div><div class="mission-label">УМОВНА МОДЕЛЬ РАДІОПОКРИТТЯ</div><h3>5G City Planner</h3><p>Розмісти до 3 базових станцій gNB і покрий принаймні 85% модельної території. Перетягуй маркери на карті та змінюй радіус.</p></div><button class="btn btn-accent" data-action="check-mission">Перевірити місію ✓</button></div><div class="device-calc-grid"><div class="panel"><div class="panel-head"><div><h3>Карта радіопокриття умовного міста</h3><p>Зелені квадрати — покриті; світлі — поза модельною зоною</p></div><span class="small-tag">RADIO PLANNING</span></div><div class="panel-body"><svg class="fiveg-map" id="fivegMap" viewBox="0 0 700 420" aria-label="Інтерактивна модель радіопокриття" role="img">${fivegSvg(cov)}</svg><div class="fiveg-settings"><label class="field full"><span>Модельний радіус покриття: <b>${s.radius} умов. од.</b></span><input class="range" type="range" min="15" max="40" value="${s.radius}" data-fiveg-radius="true"></label><div class="fiveg-site-actions"><button class="btn btn-blue" data-action="add-site" ${s.sites.length>=4?'disabled':''}>＋ Базова станція</button><button class="btn btn-danger" data-action="remove-site" ${s.sites.length<=1?'disabled':''}>− Видалити останню</button></div></div><div class="note-banner"><b>Обмеження моделі:</b> це геометричний тренажер розміщення gNB, без урахування SINR, затінення будівлями, затримки, ємності RAN, інтерференції та реальних частотних діапазонів.</div></div></div><div><div class="panel"><div class="panel-head"><h3>Результат планування</h3></div><div class="panel-body"><div class="fiveg-statline"><div class="stat-chip"><strong id="fivegPercentage">${cov.percent}%</strong><span>Умовне покриття</span></div><div class="stat-chip"><strong id="fivegSites">${cov.sites}</strong><span>Базові станції</span></div></div><div style="height:8px;background:#e6eff0;border-radius:8px;overflow:hidden;margin:20px 0 12px"><div id="fivegBar" style="height:100%;width:${cov.percent}%;background:#25bda6;border-radius:8px"></div></div><p style="font-size:11px;color:#647e86" id="fivegAdvice">${cov.percent>=85&&cov.sites<=3?'✓ Ціль досягнута: ≥85% покриття не більш як трьома станціями.':'Потрібно ≥85% покриття й не більш як 3 станції. Пересунь їх ближче до прогалин або збільш модельний радіус.'}</p><button class="btn btn-plain" data-action="reset-sites">↺ Початкова модель</button><div class="mini-section">ІНЖЕНЕРНИЙ КОМЕНТАР</div><p class="muted-help">У реальних проектах радіус дії не є вільним «регулятором»: його обмежують лінк-бюджет, частота, потужність, MIMO, покриття у приміщеннях та перешкоди. Тут радіус допомагає зрозуміти компроміс між кількістю точок і площею.</p></div></div></div></div>`;}
function fivegSvg(cov=E.coverage(state.fiveg)){let blocks='';for(let y=0;y<12;y++)for(let x=0;x<20;x++){const on=cov.cells.find(c=>c.x===x&&c.y===y).covered;blocks+=`<rect x="${x*35+1.5}" y="${y*35+1.5}" width="32" height="32" rx="4" fill="${on?'#bcecd8':'#e5edef'}" stroke="#ffffff" stroke-width="1.5"/>`;}
 let roads='<g fill="none" stroke="#91b2b5" opacity=".46" stroke-width="3">';for(let i=2;i<20;i+=5)roads+=`<path d="M${i*35} 0 V420"/>`;for(let i=3;i<12;i+=4)roads+=`<path d="M0 ${i*35} H700"/>`;roads+='</g>';
 let sites=state.fiveg.sites.map((p,i)=>`<g data-site="${i}" style="cursor:grab"><circle cx="${p.x*7}" cy="${p.y*7}" r="${state.fiveg.radius*7}" fill="#21bb9b" opacity=".09" stroke="#179b8a" stroke-width="1.7" stroke-dasharray="6 5"/><circle cx="${p.x*7}" cy="${p.y*7}" r="15" fill="#0d6f72" stroke="#fff" stroke-width="3"/><path d="M${p.x*7-6} ${p.y*7+4}l6-11 6 11M${p.x*7-3} ${p.y*7}h6" fill="none" stroke="#fff" stroke-width="1.7"/><rect x="${p.x*7+15}" y="${p.y*7-28}" width="48" height="21" rx="5" fill="#103d47"/><text x="${p.x*7+39}" y="${p.y*7-13}" font-size="11" text-anchor="middle" font-weight="800" fill="#c1fbed">gNB ${i+1}</text></g>`).join('');return blocks+roads+sites;}
function renderQuiz(){if(!quiz)return `<div class="panel"><div class="panel-body" style="text-align:center;padding:48px 30px"><div class="kicker">КОНТРОЛЬ ЗНАНЬ</div><h2 style="font-size:28px;letter-spacing:-1px;margin:12px 0">Інтерактивний іспит</h2><p style="font-size:12px;color:#78929a;max-width:560px;margin:0 auto 25px">12 випадково обраних запитань з банку 30. Кожна правильна відповідь — 1 бал. Після кожного запитання є пояснення. Наприкінці — результат за 12-бальною шкалою.</p><div class="card-grid" style="margin-bottom:25px"><div class="learning-card"><div class="big">12</div><h3>Запитань</h3><p>Усі напрями</p></div><div class="learning-card"><div class="big">4</div><h3>Варіанти</h3><p>Лише один правильний</p></div><div class="learning-card"><div class="big">12</div><h3>Максимум</h3><p>Бали за результатом</p></div></div><button class="btn btn-accent" data-action="quiz-start">Почати тестування ↗</button>${state.quizResult?`<p class="muted-help">Попередній результат: ${state.quizResult.score}/12 · ${safe(state.quizResult.date)}</p>`:''}</div></div>`;
 if(quiz.finished)return `<div class="panel"><div class="quiz-result"><div class="kicker">ТЕСТ ЗАВЕРШЕНО</div><div class="score-big">${quiz.score} / 12</div><h3>${quiz.score>=10?'Відмінна робота!':quiz.score>=7?'Добрий результат':quiz.score>=4?'Є над чим попрацювати':'Рекомендуємо повторити теорію'}</h3><p>Правильних відповідей: ${quiz.score} із 12. Усі помилки показано нижче. Результат включається до друкованого звіту.</p><div class="form-actions" style="justify-content:center;margin:22px 0"><button class="btn btn-accent" data-action="report">↗ Зберегти звіт PDF</button><button class="btn btn-plain" data-action="quiz-start">↺ Пройти ще раз</button></div><div class="quiz-results-review">${quiz.answers.map((ans,i)=>`<div>${ans.correct?'✓':'✕'} <b>${i+1}.</b> ${safe(quiz.questions[i][0])}<div style="color:#6b8d94;margin-top:4px">${safe(quiz.questions[i][3])}</div></div>`).join('')}</div></div></div>`;
 const q=quiz.questions[quiz.index],answered=quiz.chosen!=null;return `<div class="panel"><div class="panel-body"><div class="quiz-top"><div class="kicker">ЗАПИТАННЯ ${quiz.index+1} / 12</div><div class="quiz-progress">Результат: ${quiz.score} правильних</div></div><div class="progress-line" style="background:#e3edee"><span style="width:${quiz.index/12*100}%;background:#2db8a7"></span></div><h2 class="quiz-question">${safe(q[0])}</h2><div class="quiz-options">${q[1].map((o,i)=>`<button class="quiz-option ${answered?(i===q[2]?'correct':i===quiz.chosen?'incorrect':''):''}" data-action="quiz-answer" data-index="${i}" ${answered?'disabled':''}><span class="quiz-letter">${'ABCD'[i]}</span>${safe(o)}</button>`).join('')}</div>${answered?`<div class="quiz-feedback ${quiz.chosen===q[2]?'':'error'}"><b>${quiz.chosen===q[2]?'✓ Правильно!':'✕ Неправильно.'}</b> ${safe(q[3])}</div><button class="btn btn-accent" style="margin-top:20px" data-action="quiz-next">${quiz.index===11?'Завершити тестування':'Наступне запитання'} →</button>`:''}</div></div>`;}
function quizStart(){let indexes=Array.from({length:D.quiz.length},(_,i)=>i);for(let i=indexes.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[indexes[i],indexes[j]]=[indexes[j],indexes[i]];}quiz={questions:indexes.slice(0,12).map(i=>D.quiz[i]),index:0,chosen:null,score:0,answers:[],finished:false};render();}
function quizAnswer(i){if(!quiz||quiz.chosen!==null)return;quiz.chosen=i;const correct=i===quiz.questions[quiz.index][2];if(correct)quiz.score++;quiz.answers.push({chosen:i,correct});render();}
function quizNext(){if(quiz.index===11){quiz.finished=true;state.quizResult={score:quiz.score,date:new Date().toLocaleString('uk-UA'),answers:quiz.answers.map((x,i)=>({question:quiz.questions[i][0],correct:x.correct,explanation:quiz.questions[i][3]}))};toast(`Тест завершено: ${quiz.score}/12 балів!`);}else{quiz.index++;quiz.chosen=null}render();}
function markModified(){delete lastDiag[state.module];delete lastPing[state.module];flags().pingSuccess=false;flags().dnsUsed=false;persist();}
function changeModule(id){if(!D.modules.some(x=>x.id===id))return;state.module=id;state.view='lab';selected=null;selectedLink=null;connectMode=false;connectOrigin=null;$('#sidebar').classList.remove('open');render();$('#currentChapter').scrollIntoView({behavior:'smooth',block:'start'});}
function changeView(v){state.view=v;if(v==='5g')flags('5g').viewed5g=true;selectedLink=null;render();$('#viewTabs').scrollIntoView({behavior:'smooth',block:'start'});}
function addDevice(type,x=50,y=70){if(!D.deviceTypes[type])return;const s=scenario();if(s.nodes.length>=20){toast('У навчальному стенді максимум 20 пристроїв.','warn');return;}const id=`node${s.counter++}`,count=s.nodes.filter(n=>n.type===type).length+1;let node={id,type,label:`${D.deviceTypes[type].short}-${count}`,x:Math.max(7,Math.min(94,x)),y:Math.max(12,Math.min(88,y)),off:false};if(D.deviceTypes[type].ip)Object.assign(node,{ip:'192.168.10.50',prefix:24,gateway:'',dns:''});s.nodes.push(node);selected=id;selectedLink=null;markModified();render();toast(`Додано ${D.deviceTypes[type].label}. Налаштуй його параметри.`);}
function deleteSelected(){let s=scenario();if(selectedLink){s.links=s.links.filter(l=>l.id!==selectedLink);selectedLink=null;toast('Кабель видалено.');}else if(selected){s.links=s.links.filter(l=>l.a!==selected&&l.b!==selected);s.nodes=s.nodes.filter(n=>n.id!==selected);selected=null;toast('Пристрій видалено.');}markModified();render();}
function selectDevice(id){const n=nBy(id);if(!n)return;if(connectMode){if(!connectOrigin){connectOrigin=id;toast(`Початковий пристрій: ${n.label}. Тепер натисни другий вузол.`);}else if(connectOrigin===id){connectOrigin=null;toast('Вибір кабелю скасовано.');}else{const s=scenario(),a=connectOrigin,b=id;connectOrigin=null;if(s.links.some(l=>(l.a===a&&l.b===b)||(l.b===a&&l.a===b))){toast('Ці два пристрої вже мають з’єднання. Натисни на лінію, щоб його змінити.','warn');}else{s.links.push({id:`edge${s.counter++}`,a,b,media,up:true,meters:20});markModified();const l=s.links.at(-1);if(!E.supported(l,s))toast('Помилка сумісності: цей кабель не підтримується одним із пристроїв. Центр діагностики покаже спосіб виправлення.','error');else toast(`Кабель ${media}: ${nBy(a).label} ↔ ${nBy(b).label}.`);}}}else{selected=id;selectedLink=null;}render();}
function runDiag(){flags().ranDiag=true;const d=E.diagnose(scenario(),state.module,state.gpon);lastDiag[state.module]=d;render();const critical=d.filter(x=>x.level==='error').length;toast(critical?`Знайдено ${critical} критичних проблем. Нижче — причини та інструкції.`:'Критичних помилок у базовій діагностиці не знайдено.',critical?'warn':'ok');}
function runPing(){const s=scenario(),a=nBy(s.from),b=nBy(s.to),r=E.check(s,s.from,s.to);flags().pingSuccess=!!r.ok;flags().ranDiag=true;lastDiag[state.module]=E.diagnose(s,state.module,state.gpon);if(r.ok){let hops=(r.path||[]).map((id,i)=>`  ${i+1}. ${nBy(id)?.label||id}`).join('\n');lastPing[state.module]=`NETWORK LAB> ${state.module==='gpon'?'check-path':'ping'} ${b?.ip||b?.label||s.to}\n✓ ${r.reason}\nШлях у навчальній топології:\n${hops}\nСтатус: SUCCESS${r.physical?' (лише фізична зв’язність)':''}`;toast('Шлях успішний! Можна перевіряти місію.');}else{lastPing[state.module]=`NETWORK LAB> ping ${b?.ip||b?.label||s.to}\n✕ ПОМИЛКА: ${r.reason}\n→ ПІДКАЗКА: ${r.fix}\nСтатус: FAIL`;toast('Ping не пройшов. Подивись причину та підказку в журналі.','error');}render();}
function doDHCP(){const s=scenario(),pc=nBy(selected);if(!pc||!pc.dhcp){toast('Спочатку обери ПК з увімкненим DHCP.','warn');return;}const r=s.nodes.find(n=>n.type==='router'&&n.dhcpServer&&!n.off);if(!r){toast('DHCP не працює: на маршрутизаторі R-1 вимкнено DHCP-сервер. Увімкни його в інспекторі.','error');return;}if(!E.path(s,pc.id,r.id)){toast('DHCP не працює: немає фізичного шляху до DHCP-сервера. Перевір кабелі.','error');return;}pc.ip='192.168.10.100';pc.prefix=24;pc.gateway='192.168.10.1';pc.dns='192.168.20.53';flags().dhcpUsed=true;flags().pingSuccess=false;lastPing[state.module]=`NETWORK LAB> dhcp request\nDHCP DISCOVER → OFFER → REQUEST → ACK\n✓ Оренда отримана: 192.168.10.100/24\n✓ Шлюз: 192.168.10.1 · DNS: 192.168.20.53`;delete lastDiag[state.module];render();toast('DHCP успішний: ПК отримав IP, маску, шлюз і DNS.');}
function doDNS(){const s=scenario(),pc=nBy('pc1'),srv=nBy('dns1');if(state.module!=='services'||!pc||!srv){toast('DNS-місія доступна в модулі 05.','warn');return;}const r=E.check(s,pc.id,srv.id);let reason='';if(!srv.dnsServer)reason='Службу DNS на DNS-1 вимкнено. Увімкни її.';else if(pc.dns!==srv.ip)reason=`У ПК DNS-сервер ${pc.dns||'не вказано'}, а потрібно ${srv.ip}.`;else if(!r.ok)reason=r.reason+' '+r.fix;const f=flags();f.dnsUsed=!reason;if(reason){lastPing[state.module]=`NETWORK LAB> nslookup lab.example\n✕ DNS: ${reason}\n→ Виправ налаштування та повтори запит.`;toast(reason,'error');}else{lastPing[state.module]=`NETWORK LAB> nslookup lab.example\nServer: ${srv.ip}\nName: lab.example\nAddress: ${srv.ip}\n✓ DNS-запит виконаний у навчальній моделі.`;toast('DNS успішно визначив адресу lab.example.');}render();}
function checkMission(){flags().ranDiag=true;const tasks=missionTasks();const diagnostics=E.diagnose(scenario(),state.module,state.gpon),critical=diagnostics.filter(x=>x.level==='error');lastDiag[state.module]=diagnostics;if(tasks.every(Boolean)&&!critical.length){if(!state.done.includes(state.module))state.done.push(state.module);toast('Місію виконано! Результат зараховано до навчального звіту.');}else{const missing=mod().tasks.filter((_,i)=>!tasks[i]);toast(`Місію не завершено: ${missing[0]||critical[0]?.title||'виправ критичні помилки'}. Перевір критерії та діагностику.`,'warn');}render();}
function resetModule(){if(!confirm('Скинути цей стенд, його місію та налаштування?'))return;delete state.scenarios[state.module];delete state.flags[state.module];state.done=state.done.filter(x=>x!==state.module);delete lastDiag[state.module];delete lastPing[state.module];selected=null;selectedLink=null;connectMode=false;connectOrigin=null;if(state.module==='gpon')state.gpon=clone(defaults.gpon);if(state.module==='5g')state.fiveg=clone(defaults.fiveg);render();toast('Модуль повернуто до початкового стану.');}
function contextualHint(){const tasks=missionTasks(),idx=tasks.findIndex(x=>!x),d=E.diagnose(scenario(),state.module,state.gpon);const e=d.find(i=>i.level==='error')||d.find(i=>i.level==='warn');const msg=e?`${e.title}. ${e.fix}`:idx>=0?`Наступний крок: ${mod().tasks[idx]}`:'Усі критерії виконані — натисни «Перевірити місію».';toast(msg,'warn');const panel=$('.diagnostic-panel');if(panel)panel.scrollIntoView({behavior:'smooth',block:'center'});}
function openGuide(){const el=$('#guideModal');el.classList.remove('hidden');$('#closeGuide').focus()}
function closeGuide(){$('#guideModal').classList.add('hidden')}
function openReportModal(){if($('#reportModal'))return;const wrap=document.createElement('div');wrap.className='modal-overlay';wrap.id='reportModal';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="reportTitle"><button class="close-modal" data-action="close-report" aria-label="Закрити">×</button><div class="kicker">ЗВІТ ПРО ВИКОНАННЯ</div><h2 id="reportTitle">Дані студента</h2><p class="muted-help">Заповни поля — вони будуть у звіті. У вікні друку обери «Зберегти як PDF».</p><div class="student-fields"><label class="field"><span>Прізвище, ім’я</span><input id="studentName" maxlength="100" value="${safe(state.student.name)}" placeholder="Петренко Олена"></label><label class="field"><span>Навчальна група</span><input id="studentGroup" maxlength="50" value="${safe(state.student.group)}" placeholder="25-172"></label></div><div class="form-actions" style="margin-top:22px"><button class="btn btn-accent" data-action="print-report">Створити звіт ↗</button><button class="btn btn-plain" data-action="close-report">Скасувати</button></div></div>`;document.body.append(wrap);$('#studentName').focus();}
function reportHTML(){const s=scenario(),all=D.modules.map(m=>`<tr><td>${m.n}. ${safe(m.title)}</td><td>${state.done.includes(m.id)?'Виконано':'Не завершено'}</td></tr>`).join('');const log=lastPing[state.module]||'Перевірку Ping у поточному модулі не виконано.';const student=state.student;const date=new Date().toLocaleDateString('uk-UA');return `<article class="report-print"><h1 style="margin-bottom:2px">NETWORK LAB — звіт студента</h1><div style="border-bottom:2px solid #111;padding-bottom:12px;margin-bottom:18px">Дисципліна: «Вступ до спеціальності» · Електронні комунікації та радіотехніка</div><p><b>Студент:</b> ${safe(student.name||'Не вказано')}<br><b>Група:</b> ${safe(student.group||'Не вказано')}<br><b>Дата:</b> ${date}</p><h2>1. Виконання навчальних модулів</h2><table><thead><tr><th>Модуль</th><th>Результат</th></tr></thead><tbody>${all}</tbody></table><p><b>Підсумок:</b> виконано ${state.done.length} із 8 модулів.</p><h2>2. Поточний стенд: ${safe(mod().title)}</h2><p><b>Мета:</b> ${safe(mod().objective)}</p><table><thead><tr><th>Пристрій</th><th>Тип</th><th>IP / CIDR</th><th>Шлюз</th></tr></thead><tbody>${s.nodes.map(n=>`<tr><td>${safe(n.label)}</td><td>${safe(D.deviceTypes[n.type]?.label)}</td><td>${safe(n.ip?n.ip+'/'+n.prefix:'—')}</td><td>${safe(n.gateway||'—')}</td></tr>`).join('')}</tbody></table><p><b>Кабелі:</b> ${s.links.map(l=>`${safe(nBy(l.a,s)?.label)}—${safe(nBy(l.b,s)?.label)} (${safe(l.media)}, ${l.up?'UP':'DOWN'})`).join('; ')||'немає'}</p><h2>3. Контрольні критерії</h2><table><thead><tr><th>Критерій</th><th>Результат</th></tr></thead><tbody>${mod().tasks.map((t,i)=>`<tr><td>${safe(t)}</td><td>${missionTasks()[i]?'✓ Виконано':'✕ Не виконано'}</td></tr>`).join('')}</tbody></table><h2>4. Мережеве тестування</h2><pre style="white-space:pre-wrap;font-size:9pt">${safe(log)}</pre>${state.module==='gpon'?`<p><b>Оптичний запас:</b> ${E.optical(state.gpon).margin.toFixed(2)} дБ</p>`:''}${state.module==='5g'?`<p><b>Модельне покриття:</b> ${E.coverage(state.fiveg).percent}%</p>`:''}<h2>5. Перевірка знань</h2><p><b>Результат квізу:</b> ${state.quizResult?`${state.quizResult.score}/12 балів (${safe(state.quizResult.date)})`:'Ще не проходився'}</p><h2>6. Висновок</h2><p>Студент опрацював навчальний симулятор і виконав ${state.done.length} із 8 практичних модулів. Результати базуються на спрощеній локальній моделі, без реального мережевого трафіку. Звіт може бути використаний як підтвердження навчальної роботи після перевірки викладачем.</p><div style="margin-top:25px;border-top:1px solid #888;padding-top:12px">Підпис студента: _____________________</div></article>`;}
function printReport(){state.student.name=$('#studentName')?.value.trim()||'';state.student.group=$('#studentGroup')?.value.trim()||'';persist();$('#reportModal')?.remove();const root=$('#viewRoot');const prev=root.innerHTML;root.insertAdjacentHTML('beforeend',reportHTML());const printed=$('.report-print');const clean=()=>{printed?.remove();window.removeEventListener('afterprint',clean)};window.addEventListener('afterprint',clean,{once:true});setTimeout(()=>{try{window.print()}catch(err){toast('Не вдалося відкрити друк. Використай Ctrl/Cmd+P.','error')}setTimeout(clean,5000)},120);}
function updateOptics(){const o=E.optical(state.gpon);const label=$('#opticalNumber');if(!label)return;label.innerHTML=`${o.margin.toFixed(2)} <small style="font-size:18px">дБ</small>`;label.classList.toggle('bad',!o.ok);$('#opticalStatus').textContent=o.ok?'✓ Навчальний запас достатній (≥ 3 дБ).':'✕ Запас менший за 3 дБ. Зменш втрати або зміни параметри тракту.';$('#opticalLoss').textContent=o.total.toFixed(2)+' дБ';$('#opticalRx').textContent=o.rx.toFixed(2)+' дБм';$('#opticalBreakdown').innerHTML=renderOpticalBreakdown(o);}
function update5G(){const svg=$('#fivegMap');if(!svg)return;const c=E.coverage(state.fiveg);svg.innerHTML=fivegSvg(c);$('#fivegPercentage').textContent=c.percent+'%';$('#fivegSites').textContent=c.sites;$('#fivegBar').style.width=c.percent+'%';$('#fivegAdvice').textContent=c.percent>=85&&c.sites<=3?'✓ Ціль досягнута: ≥85% покриття не більш як трьома станціями.':'Потрібно ≥85% покриття й не більш як 3 станції. Пересунь їх ближче до прогалин або збільш модельний радіус.';}
function addSite(){if(state.fiveg.sites.length>=4){toast('У цьому тренажері максимум чотири базові станції. Місія вимагає не більше трьох.','warn');return;}const samples=[{x:21,y:25},{x:79,y:25},{x:50,y:48}];state.fiveg.sites.push(samples[(state.fiveg.sites.length-1)%samples.length]);render();toast('Додано базову станцію. Перетягни маркер, щоб змінити положення.');}
function closeMenuOnOutside(e){const sidebar=$('#sidebar');if(sidebar.classList.contains('open')&&!sidebar.contains(e.target)&&!e.target.closest('#menuToggle'))sidebar.classList.remove('open')}
function saveField(el){const key=el.dataset.field;const s=scenario();let target=selectedLink?s.links.find(l=>l.id===selectedLink):selected?nBy(selected):null;if(!target||!key)return;let v=el.type==='checkbox'?el.checked:el.value;if(key==='on'){target.off=!v;}else if(['prefix','meters'].includes(key))target[key]=Number(v);else if(key==='label')target[key]=(v.trim().slice(0,28)||target.label);else target[key]=v;if(key==='ip'||key==='gateway'||key==='prefix'||key==='media'||key==='up'||key==='off'||key==='dhcp')flags().pingSuccess=false;if(key==='ip'||key==='dns'||key==='dnsServer'||key==='gateway')flags().dnsUsed=false;delete lastDiag[state.module];delete lastPing[state.module];render();}
function runOSIAnimation(){const f=flags();f.osiTrace=true;const steps=$$('[data-packet-step]');if(!steps.length)return;let i=0;const timer=setInterval(()=>{steps.forEach((el,n)=>el.classList.toggle('active',n<=i));i++;if(i>=steps.length){clearInterval(timer);toast('Інкапсуляцію та декапсуляцію показано. Переглянь усі рівні OSI.');}},360);persist()}
function handleAction(btn){const a=btn.dataset.action,id=btn.dataset.id,s=scenario();if(a==='module'){changeModule(id);return;}if(a==='select-device'){if(suppressClick){suppressClick=false;return;}selectDevice(id);return;}if(a==='select-link'){selectedLink=id;selected=null;connectMode=false;connectOrigin=null;render();return;}
 if(a==='connect-mode'){connectMode=!connectMode;connectOrigin=null;selectedLink=null;render();toast(connectMode?'Натисни перший пристрій, потім другий. Кабель додається між ними.':'Режим з’єднання вимкнено.');return;}
 if(a==='add-device')return addDevice(btn.dataset.type);
 if(a==='delete-device'||a==='delete-link')return deleteSelected();
 if(a==='diagnose')return runDiag();if(a==='hint')return contextualHint();if(a==='ping')return runPing();if(a==='dhcp')return doDHCP();if(a==='dns-query')return doDNS();if(a==='check-mission')return checkMission();if(a==='reset')return resetModule();
 if(a==='focus-node'){selected=id;selectedLink=null;render();$('#inspectorRoot')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='focus-link'){selectedLink=id;selected=null;render();$('#inspectorRoot')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='go-lab'){changeView('lab');return;}if(a==='go-gpon'){changeView('gpon');return;}
 if(a==='osi-layer'){osiLayer=+btn.dataset.n;let f=flags();if(!f.osiExplored.includes(osiLayer))f.osiExplored.push(osiLayer);render();return;}
 if(a==='osi-play'){runOSIAnimation();return;}
 if(a==='subnet-calc'){subnetInput.ip=$('[data-field="subnet-ip"]')?.value.trim()||'';subnetInput.prefix=Number($('[data-field="subnet-prefix"]')?.value);$('#subnetResult').innerHTML=renderSubnetResult(E.calcSubnet(subnetInput.ip,subnetInput.prefix));return;}
 if(a==='add-site')return addSite();if(a==='remove-site'){state.fiveg.sites.pop();render();return;}if(a==='reset-sites'){state.fiveg=clone(defaults.fiveg);render();return;}
 if(a==='quiz-start'){quizStart();return;}if(a==='quiz-answer'){quizAnswer(Number(btn.dataset.index));return;}if(a==='quiz-next'){quizNext();return;}
 if(a==='report'){openReportModal();return;}if(a==='close-report'){$('#reportModal')?.remove();return;}if(a==='print-report'){printReport();return;}
}
// Керування через делегування: працює для динамічно згенерованих панелей.
document.addEventListener('click',e=>{closeMenuOnOutside(e);const action=e.target.closest('[data-action]');if(action){e.preventDefault();handleAction(action);}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='mediaSelect'){media=t.value;return;}if(t.id==='pingFrom'){scenario().from=t.value;flags().pingSuccess=false;persist();return;}if(t.id==='pingTo'){scenario().to=t.value;flags().pingSuccess=false;persist();return;}if(t.dataset.field&&['subnet-ip','subnet-prefix'].includes(t.dataset.field))return;if(t.dataset.field==='gpon-ratio'){state.gpon.ratio=Number(t.value);render();return;}if(t.dataset.field){saveField(t);return;}if(t.dataset.gpon){state.gpon[t.dataset.gpon]=Number(t.value);updateOptics();persist();return;}if(t.dataset.fivegRadius){state.fiveg.radius=Number(t.value);flags('5g').viewed5g=true;render();return;}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.gpon){state.gpon[t.dataset.gpon]=Number(t.value);const s=t.closest('.field')?.querySelector('span strong');if(s)s.textContent=t.value+' '+({km:'км',atten:'дБ/км',tx:'дБм',sens:'дБм',connectors:'шт.',splices:'шт.'}[t.dataset.gpon]||'');updateOptics();}if(t.dataset.fivegRadius){state.fiveg.radius=Number(t.value);const span=t.closest('.field')?.querySelector('span b');if(span)span.textContent=t.value+' умов. од.';flags('5g').viewed5g=true;update5G();}});
$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#heroStart').addEventListener('click',()=>changeView('lab'));
$('#heroGuide').addEventListener('click',openGuide);
$('#closeGuide').addEventListener('click',closeGuide);
$('#guideGo').addEventListener('click',()=>{closeGuide();changeView('lab')});
$('#guideModal').addEventListener('click',e=>{if(e.target.id==='guideModal')closeGuide()});
$('#headerReport').addEventListener('click',openReportModal);
$('#viewTabs').addEventListener('click',e=>{const btn=e.target.closest('[data-view]');if(btn)changeView(btn.dataset.view)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeGuide();$('#reportModal')?.remove();if(connectMode){connectMode=false;connectOrigin=null;render();}}});
// Перетягування вузлів мережі та базових станцій (із підтримкою миші/дотику).
document.addEventListener('pointerdown',e=>{const device=e.target.closest('.net-node');if(device&&!connectMode&&e.button===0){const canvas=$('#networkCanvas');if(!canvas)return;const n=nBy(device.dataset.id);if(!n)return;dragging={id:n.id,x:e.clientX,y:e.clientY,ox:n.x,oy:n.y,moved:false};return;}const site=e.target.closest('[data-site]');if(site&&$('#fivegMap')&&e.button===0){siteDrag={i:+site.dataset.site};e.preventDefault();}});
document.addEventListener('pointermove',e=>{if(dragging){const canvas=$('#networkCanvas');if(!canvas)return;const rect=canvas.getBoundingClientRect();const dx=e.clientX-dragging.x,dy=e.clientY-dragging.y;if(Math.abs(dx)+Math.abs(dy)<4&&!dragging.moved)return;dragging.moved=true;const n=nBy(dragging.id);if(n){n.x=Math.max(6,Math.min(94,dragging.ox+100*dx/rect.width));n.y=Math.max(12,Math.min(88,dragging.oy+100*dy/rect.height));const el=canvas.querySelector(`[data-id="${CSS.escape(n.id)}"].net-node`);if(el){el.style.left=n.x+'%';el.style.top=n.y+'%'}$('#connectionsSvg').innerHTML=renderConnections();}return;}if(siteDrag){const map=$('#fivegMap');if(!map)return;const rect=map.getBoundingClientRect();const p=state.fiveg.sites[siteDrag.i];if(!p)return;p.x=Math.max(2,Math.min(98,100*(e.clientX-rect.left)/rect.width));p.y=Math.max(2,Math.min(58,60*(e.clientY-rect.top)/rect.height));flags('5g').viewed5g=true;update5G();}});
document.addEventListener('pointerup',()=>{if(dragging){if(dragging.moved){suppressClick=true;setTimeout(()=>suppressClick=false,200);persist()}dragging=null;}if(siteDrag){siteDrag=null;persist()}});
// Drag-and-drop пристрою з палітри на поле стенда.
document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-drag-type]');if(!b)return;e.dataTransfer.setData('text/plain',b.dataset.dragType);e.dataTransfer.effectAllowed='copy';});
document.addEventListener('dragover',e=>{if(e.target.closest('#networkCanvas'))e.preventDefault()});
document.addEventListener('drop',e=>{const c=e.target.closest('#networkCanvas');if(!c)return;e.preventDefault();const type=e.dataTransfer.getData('text/plain');if(!D.deviceTypes[type])return;const rect=c.getBoundingClientRect();addDevice(type,100*(e.clientX-rect.left)/rect.width,100*(e.clientY-rect.top)/rect.height)});
scenario();render();
